import numpy as np
import time


def _score(h):
    """Exact R(f) for step heights h (up to scale)."""
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
        return -1.0
    if h.min() < 0:
        return -1.0
    conv = np.convolve(h, h)
    L = np.concatenate(([0.0], conv, [0.0]))
    l2 = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    l1 = h.sum() ** 2
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2 / (l1 * linf)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    def out_of_time():
        return time.process_time() > deadline

    # Candidate pool of (score, heights)
    best_h = None
    best_s = -1.0

    def consider(h):
        nonlocal best_h, best_s
        h = np.asarray(h, dtype=float)
        if h.size < 1 or h.size > 50000:
            return
        if not np.all(np.isfinite(h)) or h.min() < 0 or h.sum() <= 0:
            return
        s = _score(h)
        if s > best_s:
            best_s = s
            best_h = h.copy()

    if start is not None:
        try:
            consider(np.asarray(start, dtype=float))
        except Exception:
            pass

    rng = np.random.default_rng(12345)

    # Family of parametric shapes to try. The autoconvolution of a
    # slowly-varying shape is concentrated, boosting R above 2/3.
    def make_shape(N, kind, p):
        x = np.linspace(-1.0, 1.0, N)
        if kind == 0:  # raised cosine
            return (np.cos(np.pi * x / 2.0) ** p).clip(0)
        if kind == 1:  # gaussian
            return np.exp(-p * x * x)
        if kind == 2:  # superellipse / cosine^p with different
            return (1.0 - np.abs(x) ** p).clip(0)
        if kind == 3:  # asymmetric-ish: exp(-p*|x|)
            return np.exp(-p * np.abs(x))
        if kind == 4:  # triangular-ish
            return (1.0 - np.abs(x)).clip(0) ** p
        return np.ones(N)

    # Coarse grid search over families
    Ns = [25, 50, 100, 200, 400, 800, 1600, 3200, 5000]
    kinds = [0, 1, 2, 3, 4]
    ps = [0.25, 0.5, 1.0, 2.0, 3.0, 4.0, 6.0, 8.0, 12.0]

    for N in Ns:
        for kind in kinds:
            for p in ps:
                if out_of_time():
                    break
                consider(make_shape(N, kind, p))
            if out_of_time():
                break
        if out_of_time():
            break

    # Local hill-climb / random perturbation refinement of the best shape
    if best_h is None:
        best_h = np.ones(50)
        best_s = _score(best_h)

    current = best_h.copy()
    current_s = best_s

    # Try smoothing/upsampling the best shape (smoother -> more concentrated conv)
    def smooth(h, k):
        if k <= 1:
            return h
        kernel = np.ones(k) / k
        return np.convolve(h, kernel, mode='same')

    # Multi-resolution refinement: perturb, smooth, resample
    step = 0
    while not out_of_time():
        step += 1
        cand = current.copy()

        # Random operation
        op = rng.integers(0, 4)
        if op == 0:
            # multiplicative noise
            noise = np.exp(rng.normal(0, 0.05, cand.size))
            cand = cand * noise
        elif op == 1:
            # additive bump
            i = rng.integers(0, cand.size)
            w = max(1, cand.size // 20)
            lo = max(0, i - w)
            hi = min(cand.size, i + w)
            cand[lo:hi] += rng.normal(0, 0.1) * cand.max()
        elif op == 2:
            # smoothing
            k = int(rng.integers(2, max(3, cand.size // 10 + 2)))
            cand = smooth(cand, k)
        else:
            # resample to slightly different size
            newN = int(cand.size + rng.integers(-max(1, cand.size // 10), max(2, cand.size // 10)))
            newN = max(1, min(50000, newN))
            xi = np.linspace(0, 1, cand.size)
            xn = np.linspace(0, 1, newN)
            cand = np.interp(xn, xi, cand)

        cand = cand.clip(0)
        if cand.sum() <= 0:
            continue

        s = _score(cand)
        if s > current_s or (rng.random() < 0.02 and s > current_s - 0.001):
            current = cand
            current_s = s
            if s > best_s:
                best_s = s
                best_h = cand.copy()

        # Periodic restart from best with stronger perturbation
        if step % 200 == 0:
            current = best_h.copy()
            current_s = best_s

    return np.asarray(best_h, dtype=float)

