import numpy as np
import time


def _score(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
        return -1.0
    if h.min() < 0:
        return -1.0
    conv = np.convolve(h, h)
    L = np.concatenate(([0.0], conv, [0.0]))
    l2 = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    l1 = h.sum() ** 2
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2 / (l1 * linf)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    def out_of_time():
        return time.process_time() > deadline

    best_h = None
    best_s = -1.0

    def consider(h):
        nonlocal best_h, best_s
        h = np.asarray(h, dtype=float)
        if h.size < 1 or h.size > 50000:
            return
        if not np.all(np.isfinite(h)) or h.min() < 0 or h.sum() <= 0:
            return
        s = _score(h)
        if s > best_s:
            best_s = s
            best_h = h.copy()

    if start is not None:
        try:
            consider(np.asarray(start, dtype=float))
        except Exception:
            pass

    rng = np.random.default_rng(98765)

    # Key insight: R is maximized when f*f is as flat-topped (rectangular) as
    # possible relative to its L2/L1. A plateau-shaped convolution with sharp
    # edges gives high ||f*f||_inf while keeping ||f*f||_2^2 modest.
    #
    # A good family: f itself roughly a "bump" whose convolution approximates
    # a trapezoid/rectangle. Try a wide variety of smooth bump families.

    def make_shape(N, kind, p, q=1.0):
        x = np.linspace(-1.0, 1.0, N)
        if kind == 0:
            return np.cos(np.pi * x / 2.0) ** p
        if kind == 1:
            return np.exp(-p * x * x)
        if kind == 2:
            return (1.0 - np.abs(x) ** p).clip(0)
        if kind == 3:
            return np.exp(-p * np.abs(x))
        if kind == 4:
            return (1.0 - np.abs(x)).clip(0) ** p
        if kind == 5:  # flat-top bump: 1 in center, cosine taper
            a = min(1.0, max(0.0, p))
            w = 1.0 - a
            y = np.zeros_like(x)
            core = np.abs(x) <= w
            y[core] = 1.0
            edge = (~core) & (np.abs(x) < 1.0)
            t = (np.abs(x[edge]) - w) / max(1e-9, (1.0 - w))
            y[edge] = np.cos(np.pi * t / 2.0) ** q
            return y
        if kind == 6:  # power of a flat-top (sharper edges)
            y = make_shape(N, 5, p, 1.0)
            return y ** q
        if kind == 7:  # supergaussian
            return np.exp(-(np.abs(x) ** p)) ** q
        return np.ones(N)

    Ns = [30, 60, 100, 150, 250, 400, 700, 1200, 2000, 3500, 6000]
    ps = [0.2, 0.35, 0.5, 0.7, 0.85, 0.95, 1.0, 1.5, 2.0, 3.0, 4.0, 6.0, 8.0]
    qs = [0.5, 1.0, 2.0, 4.0]

    for N in Ns:
        for kind in range(8):
            for p in ps:
                if out_of_time():
                    break
                if kind in (5,):
                    consider(make_shape(N, kind, p, 1.0))
                    consider(make_shape(N, kind, p, 2.0))
                    consider(make_shape(N, kind, p, 4.0))
                elif kind == 6:
                    for q in qs:
                        consider(make_shape(N, kind, p, q))
                elif kind == 7:
                    for q in qs:
                        consider(make_shape(N, kind, p, q))
                else:
                    consider(make_shape(N, kind, p))
            if out_of_time():
                break
        if out_of_time():
            break

    if best_h is None:
        best_h = np.ones(50)
        best_s = _score(best_h)

    # Local refinement: coordinate-wise multiplicative + smooth perturbations.
    current = best_h.copy()
    current_s = best_s
    n = current.size

    def smooth(h, k):
        if k <= 1:
            return h
        kernel = np.ones(k) / k
        return np.convolve(h, kernel, mode='same')

    step = 0
    temp = 0.03
    while not out_of_time():
        step += 1
        cand = current.copy()
        op = rng.integers(0, 6)
        if op == 0:
            cand = cand * np.exp(rng.normal(0, 0.02 + temp, cand.size))
        elif op == 1:
            # smooth perturbation
            noise = rng.normal(0, 1.0, cand.size)
            k = max(1, int(rng.integers(1, max(2, cand.size // 8))))
            noise = smooth(noise, k)
            cand = cand + (0.05 + temp) * cand.max() * noise
        elif op == 2:
            k = int(rng.integers(2, max(3, cand.size // 15 + 2)))
            cand = smooth(cand, k)
        elif op == 3:
            # resample (adjust N)
            newN = int(cand.size + rng.integers(-max(1, cand.size // 15),
                                                max(2, cand.size // 15)))
            newN = max(5, min(50000, newN))
            xi = np.linspace(0, 1, cand.size)
            xn = np.linspace(0, 1, newN)
            cand = np.interp(xn, xi, cand)
        elif op == 4:
            # sharpen edges via power on normalized shape
            mx = cand.max()
            if mx > 0:
                pw = 1.0 + rng.normal(0, 0.15)
                cand = mx * (cand / mx) ** max(0.1, pw)
        else:
            # flat-top morph: raise the middle toward max
            mx = cand.max()
            if mx > 0:
                frac = rng.uniform(0.0, 0.5)
                lo = int(frac * cand.size)
                hi = cand.size - lo
                cand[lo:hi] = np.maximum(cand[lo:hi], mx * rng.uniform(0.6, 1.0))

        cand = np.clip(cand, 0, None)
        if cand.sum() <= 0:
            continue
        s = _score(cand)
        if s > current_s or rng.random() < 0.05:
            if s > current_s:
                current = cand
                current_s = s
                if s > best_s:
                    best_s = s
                    best_h = cand.copy()
            else:
                # occasionally accept worse to escape local optima
                if rng.random() < 0.3:
                    current = cand
                    current_s = s

        if step % 300 == 0:
            current = best_h.copy()
            current_s = best_s
            temp = 0.03 * (1.0 + rng.random())

    return np.asarray(best_h, dtype=float)

