        if kind == 4:
            return (1.0 - np.abs(x)).clip(0) ** p
        return np.ones(N)

    for N in [25, 50, 100, 200, 400, 800, 1600, 3200, 5000]:
        for kind in range(5):
            for p in [0.25, 0.5, 1.0, 2.0, 3.0, 4.0, 6.0, 8.0, 12.0]:
                if oot():
                    break
                consider(make_shape(N, kind, p))
            if oot():
                break
        if oot():
            break

    if best_h is None:
        best_h = np.ones(64)
        best_s = _score(best_h)

    # Coordinate-wise refinement: for each height, try scaling it up/down
    # and accept if score improves. This is direct optimization of R.
    current = best_h.copy()
    current_s = best_s

    def try_cand(cand):
        nonlocal current, current_s, best_h, best_s
        cand = np.asarray(cand, dtype=float)
        if cand.size < 1 or cand.size > 50000:
            return False
        if not np.all(np.isfinite(cand)):
            return False
        cand = cand.clip(0)
        if cand.sum() <= 0:
            return False
        s = _score(cand)
        if s > current_s:
            current = cand.copy()
            current_s = s
            if s > best_s:
                best_s = s
                best_h = cand.copy()
            return True
        return False

    # Coordinate ascent phase
    iteration = 0
    while not oot():
        iteration += 1
        improved = False
        n = current.size
        # Try multiply each position by factors
        factors = [0.5, 0.7, 0.85, 1.15, 1.3, 1.5]
        order = rng.permutation(n)
        for idx in order:
            if oot():
                break
            for f in factors:
                cand = current.copy()
                cand[idx] *= f
                if try_cand(cand):
                    improved = True
                    break
        if not improved:
            # Try resample / grow / shrink
            newN = n + (1 if rng.random() < 0.5 else -1) * max(1, n // 8)
            newN = max(1, min(50000, newN))
            xi = np.linspace(0, 1, n)
            xn = np.linspace(0, 1, newN)
            cand = np.interp(xn, xi, current)
            if try_cand(cand):
                continue
            # Random perturbation of a few entries
            cand = current.copy()
            k = max(1, n // 10)
            idxs = rng.choice(n, size=min(k, n), replace=False)
            cand[idxs] *= np.exp(rng.normal(0, 0.1, size=idxs.size))
            if try_cand(cand):
                continue
            # Restart from best with smoothing
            current = best_h.copy()
            current_s = best_s
            k = int(rng.integers(2, max(3, n // 8 + 2)))
            kernel = np.ones(k) / k
            current = np.convolve(current, kernel, mode='same')
            if current.sum() > 0:
                current_s = _score(current)
            if current_s < 0:
                current = best_h.copy()
                current_s = best_s

    return np.asarray(best_h, dtype=float)

import numpy as np
import time


def _score(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0 or h.min() < 0:
        return -1.0
    conv = np.convolve(h, h)
    L = np.concatenate(([0.0], conv, [0.0]))
    l2 = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    l1 = h.sum() ** 2
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2 / (l1 * linf)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    def oot():
        return time.process_time() > deadline

    best_h = None
    best_s = -1.0

    def consider(h):
        nonlocal best_h, best_s
        h = np.asarray(h, dtype=float)
        if h.size < 1 or h.size > 50000:
            return
        if not np.all(np.isfinite(h)) or h.min() < 0 or h.sum() <= 0:
            return
        s = _score(h)
        if s > best_s:
            best_s = s
            best_h = h.copy()

    if start is not None:
        try:
            consider(np.asarray(start, dtype=float))
        except Exception:
            pass

    rng = np.random.default_rng(12345)

    # Key insight: the near-optimal shape looks like a concave, plateau-ish
    # bump (raised cosine / smooth one-hump). Autoconvolution of such a
    # shape is concentrated -- its knots near the peak are dense, so the
    # L2/L1/Linf ratio is high. We focus the search on smooth one-humps
    # with a controllable flatness exponent and width, then do a fine
    # coordinate hill-climb that respects smoothness (the true optimum
    # is smooth; noise hurts).

    def make_shape(N, kind, p):
        x = np.linspace(-1.0, 1.0, N)
        if kind == 0:
            return (np.cos(np.pi * x / 2.0) ** p).clip(0)
        if kind == 1:
            return np.exp(-p * x * x)
        if kind == 2:
            return (1.0 - np.abs(x) ** p).clip(0)
        if kind == 3:
            return np.exp(-p * np.abs(x))
        if kind == 4:
            return (1.0 - np.abs(x)).clip(0) ** p
        return np.ones(N)

    # Coarse grid: broad sweep over N and shape family
    Ns = [20, 30, 40, 50, 60, 70, 80, 100, 130, 160, 200, 260, 340, 450,
          600, 800, 1100, 1500, 2000, 3000, 4000, 6000]
    kinds = [0, 1, 2, 3, 4]
    ps = [0.25, 0.4, 0.5, 0.7, 1.0, 1.5, 2.0, 3.0, 4.0, 6.0, 8.0, 12.0, 16.0]

    for N in Ns:
        for kind in kinds:
            for p in ps:
                if oot():
                    break
                consider(make_shape(N, kind, p))
            if oot():
                break
        if oot():
            break

    if best_h is None:
        best_h = np.ones(50)
        best_s = _score(best_h)

    # Fine local refinement with a smoothness prior: perturb via low-order
    # polynomial / low-frequency Fourier modes and small multiplicative
    # noise, plus resampling to nearby N. Accept only improvements.
    current = best_h.copy().astype(float)
    current_s = best_s

    def smooth(h, k):
        if k <= 1:
            return h
        kernel = np.ones(k) / k
        return np.convolve(h, kernel, mode='same')

    def resample(h, newN):
        xi = np.linspace(0, 1, h.size)
        xn = np.linspace(0, 1, newN)
        return np.interp(xn, xi, h)

    step = 0
    stall = 0
    while not oot():
        step += 1
        cand = current.copy()
        op = rng.integers(0, 6)
        if op == 0:
            # multiplicative noise (small)
            cand = cand * np.exp(rng.normal(0, 0.02, cand.size))
        elif op == 1:
            # low-frequency Fourier perturbation
            n = cand.size
            x = np.linspace(0, 1, n)
            for _ in range(rng.integers(1, 3)):
                k = int(rng.integers(1, max(2, n // 8 + 2)))
                a = rng.normal(0, 0.01) * cand.max()
                cand = cand + a * np.sin(np.pi * k * x)
        elif op == 2:
            # smoothing pass
            k = int(rng.integers(2, max(3, cand.size // 15 + 2)))
            cand = smooth(cand, k)
        elif op == 3:
            # resample to nearby N
            newN = int(cand.size + rng.integers(-max(1, cand.size // 25),
                                                max(2, cand.size // 25)))
            newN = max(1, min(50000, newN))
            cand = resample(cand, newN)
        elif op == 4:
            # gentle bump
            i = rng.integers(0, cand.size)
            w = max(1, cand.size // 25)
            lo = max(0, i - w)
            hi = min(cand.size, i + w)
            cand[lo:hi] += rng.normal(0, 0.03) * cand.max()
        else:
            # small shift of the whole shape
            sh = int(rng.integers(-max(1, cand.size // 50),
                                  max(2, cand.size // 50)))
            cand = np.roll(cand, sh)
            if sh > 0:
                cand[:sh] = 0
            elif sh < 0:
                cand[sh:] = 0

        cand = cand.clip(0)
        if cand.sum() <= 0:
            continue

        s = _score(cand)
        if s > current_s:
            current = cand
            current_s = s
            stall = 0
            if s > best_s:
                best_s = s
                best_h = cand.copy()
        else:
            stall += 1

        # Restart from best on stagnation, with a mild perturbation
        if stall > 300:
            current = best_h.copy().astype(float)
            if rng.random() < 0.5:
                current = current * np.exp(rng.normal(0, 0.03, current.size))
                current = current.clip(0)
            current_s = _score(current)
            stall = 0

    return np.asarray(best_h, dtype=float)

