    L = np.concatenate(([0.0], conv, [0.0]))
    a = L[:-1]
    b = L[1:]
    l2 = np.sum(a * a + a * b + b * b) / 3.0
    l1 = h.sum() ** 2
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2 / (l1 * linf)


def _score_and_grad(h):
    h = np.asarray(h, dtype=float)
    n = h.size
    conv = np.convolve(h, h)
    L = np.concatenate(([0.0], conv, [0.0]))
    a = L[:-1]
    b = L[1:]
    quad = a * a + a * b + b * b
    l2 = np.sum(quad) / 3.0
    l1 = h.sum() ** 2
    imax = int(np.argmax(L))
    linf = L[imax]
    R = l2 / (l1 * linf)

    dquad_dL = np.zeros_like(L)
    dquad_dL[:-1] += 2.0 * a + b
    dquad_dL[1:] += a + 2.0 * b
    dl2_dL = dquad_dL / 3.0

    dconv = dl2_dL[1:2 * n - 1]
    full = np.convolve(dconv, h[::-1])
    dl2_dh = 2.0 * full[n - 1: n - 1 + n]

    dl1_dh = 2.0 * h.sum() * np.ones(n)
    dlinf_dh = np.zeros(n)
    if 1 <= imax <= 2 * n - 1:
        k = imax - 1
        lo = max(0, k - (n - 1))
        hi = min(n - 1, k) + 1
        idx = np.arange(lo, hi)
        dlinf_dh[idx] = 2.0 * h[k - idx]

    denom = l1 * linf
    dR_dh = (dl2_dh * denom - l2 * (dl1_dh * linf + l1 * dlinf_dh)) / (denom * denom)
    return R, dR_dh


