    state = {"best_h": None, "best_s": -1.0}

    def consider(h):
        h = np.asarray(h, dtype=float)
        if h.size < 1 or h.size > 50000:
            return False
        if not np.all(np.isfinite(h)) or h.min() < 0 or h.sum() <= 0:
            return False
        s = _score(h)
        if s > state["best_s"]:
            state["best_s"] = s
            state["best_h"] = h.copy()
            return True
        return False

    if start is not None:
        try:
            consider(np.asarray(start, dtype=float))
        except Exception:
            pass

