    kinds = [0, 1, 2, 3, 4]
    ps = [0.25, 0.5, 1.0, 2.0, 3.0, 4.0, 6.0, 8.0, 12.0]
    for N in Ns:
        for kind in kinds:
            for p in ps:
                if out_of_time():
