            return h
        kernel = np.ones(k) / k
        return np.convolve(h, kernel, mode='same')

    # KEY CHANGE: gradient ascent that optimizes the actual R (with active constraint
    # on linf) using log-space step and adaptive step retry, plus a fallback to
    # plain descent on -R when the analytic gradient seems noisy.
