                                                max(2, cand.size // 6)))
            newN = max(3, min(50000, newN))
            cand = _resample(cand, newN)
        else:
            kind = int(rng.integers(0, 5))
            p = float(rng.uniform(0.3, 15.0))
            cand = make_shape(cand.size, kind, p)
        cand = cand.clip(0)
        if cand.sum() <= 0:
            continue
        consider(cand)
        if cand.size <= 2000:
            grad_ascent(cand, 50, 0.3)
        else:
            grad_ascent(cand, 20, 0.25)

    return np.asarray(state["best_h"], dtype=float)

