    conv = np.convolve(h, h)
    L = np.concatenate(([0.0], conv, [0.0]))
    a = L[:-1]; b = L[1:]
    l2 = np.sum(a * a + a * b + b * b) / 3.0
    l1 = h.sum() ** 2
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2 / (l1 * linf)


def _score_and_grad(h):
    h = np.asarray(h, dtype=float)
    n = h.size
    conv = np.convolve(h, h)
    L = np.concatenate(([0.0], conv, [0.0]))
    a = L[:-1]; b = L[1:]
    l2 = np.sum(a * a + a * b + b * b) / 3.0
    l1 = h.sum() ** 2
    imax = int(np.argmax(L))
    linf = L[imax]
    R = l2 / (l1 * linf)

