def _score_many(H):
    # H: (M, N) array of candidate heights. Returns scores.
    M, N = H.shape
    out = np.empty(M)
    for i in range(M):
        out[i] = _score(H[i])
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    def oot():
