    # Phase 1: refine start with pattern search
    pattern_search(best_h, 400, 0.08, patience=12)

    # Phase 2: N-search with resampling + local refinement
    base_N = best_h.size
    for dn in [-20, -10, -5, -2, -1, 1, 2, 5, 10, 20, 40]:
        if oot():
            break
        nn = base_N + dn
        if 5 <= nn <= 50000:
