            consider(cand)
            pattern_search(cand, 60, 0.05, patience=8)

    # Phase 3: iterated local search with restarts
    while not oot():
        cand = best_h.copy()
        op = rng.integers(0, 6)
        if op == 0:
            cand = cand * np.exp(rng.normal(0, 0.03, cand.size))
        elif op == 1:
            i = rng.integers(0, cand.size)
