        elif op == 3:
            newN = cand.size + int(rng.integers(-max(1, cand.size // 5),
                                                max(2, cand.size // 5)))
            newN = max(5, min(50000, newN))
            cand = _resample(cand, newN)
        elif op == 4:
            kind = int(rng.integers(0, 5))
            p = float(rng.uniform(0.3, 15.0))
            cand = make_shape(cand.size, kind, p)
        else:
            x = np.linspace(-1, 1, cand.size)
