    a = L[:-1]; b = L[1:]
    l2 = np.sum(a * a + a * b + b * b) / 3.0
    l1 = h.sum() ** 2
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2 / (l1 * linf)


def _resample(h, newN):
    if newN == h.size:
        return h.copy()
    xi = np.linspace(0, 1, h.size)
    xn = np.linspace(0, 1, newN)
    return np.interp(xn, xi, h)


def _score_batch(H):
    # Vectorised scoring of many candidates at once.
    M, N = H.shape
    if M == 0:
        return np.empty(0)
    # Pad for FFT-free convolution via np.convolve per row is slow; use
    # matrix approach: full conv length 2N-1.
    out = np.empty(M)
    for i in range(M):
        h = H[i]
        conv = np.convolve(h, h)
        L = np.empty(conv.size + 2)
        L[0] = 0.0
        L[-1] = 0.0
        L[1:-1] = conv
        a = L[:-1]; b = L[1:]
        l2 = np.dot(a, a + b) + np.dot(b, b)
        l2 /= 3.0
        l1 = h.sum() ** 2
        linf = L.max()
        out[i] = l2 / (l1 * linf) if linf > 0 and l1 > 0 else -1.0
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.82

    def oot():
